// Verification host. VM-prepared storage tests reference publication, not stream constructors or IO.
using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
public static class BoomSystemStreamsProbe {
    [StructLayout(LayoutKind.Sequential)] struct Context {public uint Kind,PC,Method,Depth;}
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode)] static extern IntPtr LoadLibraryExW(string p,IntPtr z,uint f);
    [DllImport("kernel32.dll",CharSet=CharSet.Ansi)] static extern IntPtr GetProcAddress(IntPtr m,string n);
    [DllImport("kernel32.dll")] static extern bool FreeLibrary(IntPtr m);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Create(ulong n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int Bind(IntPtr h);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int Destroy(IntPtr h);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Get();
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Storage(uint id);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate ulong Entry(ref Context c,[In] ulong[] a);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate ulong Set(ref Context c,[In] ulong[] a,IntPtr pool,uint op);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Roots(out uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate ulong Collect(IntPtr h,IntPtr roots,uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Alloc(IntPtr h,ulong bytes,uint refs,uint type);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr New(IntPtr h,IntPtr layout,ref Context c);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr PoolCreate(uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate uint PoolRun(IntPtr p,IntPtr fn,IntPtr input,IntPtr output,uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate uint PoolDestroy(IntPtr p);
    static void Check(bool ok,string s){if(!ok)throw new Exception(s);}
    static T Fn<T>(IntPtr m,string n){IntPtr p=GetProcAddress(m,n);Check(p!=IntPtr.Zero,"Missing "+n);return Marshal.GetDelegateForFunctionPointer<T>(p);}
    static ulong Bits(IntPtr p){return unchecked((ulong)p.ToInt64());}
    static IntPtr Cell(IntPtr pool,uint op){return Marshal.ReadIntPtr(Marshal.ReadIntPtr(pool,32),checked((int)op*16));}
    static void Put(Set f,IntPtr pool,uint op,IntPtr value){var c=new Context();Check(f(ref c,new ulong[]{Bits(value)},pool,op)==0&&c.Kind==0&&c.Depth==0&&Marshal.ReadIntPtr(Cell(pool,op))==value,"System stream publication failed: "+c.Kind);}
    static int Reachable(IntPtr roots,uint n){var seen=new HashSet<IntPtr>();var todo=new Stack<IntPtr>();for(int i=0;i<n;i++)todo.Push(Marshal.ReadIntPtr(roots,i*8));while(todo.Count!=0){IntPtr p=todo.Pop();if(p==IntPtr.Zero||!seen.Add(p))continue;uint f=unchecked((uint)Marshal.ReadInt32(p,-24)),refs=unchecked((uint)Marshal.ReadInt32(p,-20));long bytes=Marshal.ReadInt64(p,-16);Check((f&0xfffffffd)==0xb00b0001&&bytes>=0&&refs<=(ulong)bytes/8&&seen.Count<1048576,"Malformed stream root graph");for(int i=0;i<refs;i++)todo.Push(Marshal.ReadIntPtr(p,i*8));}return seen.Count;}
    static void GC(IntPtr m,IntPtr h,params IntPtr[] extra){IntPtr roots=Fn<Roots>(m,"boom_get_static_roots")(out uint n),all=Marshal.AllocHGlobal(checked(((int)n+extra.Length)*8));try{for(int i=0;i<n;i++)Marshal.WriteIntPtr(all,i*8,Marshal.ReadIntPtr(roots,i*8));for(int i=0;i<extra.Length;i++)Marshal.WriteIntPtr(all,((int)n+i)*8,extra[i]);uint count=checked(n+(uint)extra.Length);int live=Reachable(all,count);Check(Fn<Collect>(m,"boom_heap_collect")(h,all,count)!=ulong.MaxValue&&Marshal.ReadInt64(h,56)==live,"Stream static root graph mismatch");}finally{Marshal.FreeHGlobal(all);}}
    static void Workers(IntPtr m,IntPtr r,IntPtr[] values){const uint n=2049;IntPtr pool=IntPtr.Zero,input=IntPtr.Zero,output=IntPtr.Zero;try{pool=Fn<PoolCreate>(r,"boom_pool_create")(8);Check(pool!=IntPtr.Zero,"Stream workers failed");input=Marshal.AllocHGlobal((int)n*128);output=Marshal.AllocHGlobal((int)n*32);for(int i=0;i<n;i++)Marshal.WriteInt64(input,i*128,values[i%values.Length].ToInt64());for(int batch=0;batch<3;batch++){Check(Fn<PoolRun>(r,"boom_pool_run")(pool,GetProcAddress(m,"boom_entry"),input,output,n)==0,"Stream worker batch failed");for(int i=0;i<n;i++)Check(Marshal.ReadInt64(output,i*32)==0&&Marshal.ReadInt64(output,i*32+8)==0&&Marshal.ReadInt64(output,i*32+16)==0&&Marshal.ReadInt64(output,i*32+24)==0,"Stream worker result or context mismatch");}}finally{if(pool!=IntPtr.Zero)Check(Fn<PoolDestroy>(r,"boom_pool_destroy")(pool)==0,"Stream workers still active");if(input!=IntPtr.Zero)Marshal.FreeHGlobal(input);if(output!=IntPtr.Zero)Marshal.FreeHGlobal(output);}}
    public static void Run(string dll,string runtime,uint entryOp,int bufOffset,int[] expected){
        IntPtr m=LoadLibraryExW(dll,IntPtr.Zero,0x1100),r=LoadLibraryExW(runtime,IntPtr.Zero,0x1100),h=IntPtr.Zero;Check(m!=IntPtr.Zero&&r!=IntPtr.Zero,"System stream module load failed");
        try{h=Fn<Create>(m,"boom_heap_create")(1024*1024);Check(h!=IntPtr.Zero&&Fn<Bind>(m,"boom_bind_heap")(h)==1&&expected.Length==1024,"System stream setup failed");IntPtr pool=Fn<Get>(m,"boom_get_system_stream_pool")();var set=Fn<Set>(m,"boom_system_stream_set");IntPtr cls=Marshal.ReadIntPtr(pool,8);Check(Marshal.ReadInt32(cls,8)==0,"System class was not cold");
            var c=new Context{PC=17,Method=23};Check(set(ref c,new ulong[]{0},pool,0)==0&&c.Kind==7&&c.PC==17&&c.Method==23,"Raw setter accepted uninitialized System");Workers(m,r,new[]{IntPtr.Zero});Check(Marshal.ReadInt32(cls,8)==2,"Original System initializer did not execute");GC(m,h);long baseline=Marshal.ReadInt64(h,56);
            var alloc=Fn<Alloc>(r,"boom_heap_alloc");var obj=Fn<New>(r,"boom_object_new");var storage=Fn<Storage>(m,"boom_get_stream_storage");var values=new IntPtr[5];
            for(int i=1;i<=4;i++){c=new Context();values[i]=obj(h,storage(i<=2?0U:1U),ref c);Check(values[i]!=IntPtr.Zero&&c.Kind==0,"VM stream storage allocation failed");if(i<=2){IntPtr b=alloc(h,2,0,264);Check(b!=IntPtr.Zero,"VM input backing allocation failed");Marshal.WriteInt16(b,0,unchecked((short)(0x100+i)));Marshal.WriteIntPtr(values[i],bufOffset,b);}}
            long count=Marshal.ReadInt64(h,56);for(uint op=0;op<3;op++)Put(set,pool,op,IntPtr.Zero);
            var entry=Fn<Entry>(m,"boom_entry");for(int i=0;i<128;i++){IntPtr value=values[(entryOp==0?1:3)+(i&1)];c=new Context();Check(entry(ref c,new ulong[]{Bits(value)})==0&&c.Kind==0&&Marshal.ReadIntPtr(Cell(pool,entryOp))==value&&Marshal.ReadInt64(h,56)==count,"Native source entry did not publish its argument without allocation");}for(uint op=0;op<3;op++)Put(set,pool,op,IntPtr.Zero);
            for(int i=0;i<1024;i++){uint op=(uint)(i%3);int choice=i%5==0?0:op==0?1+(i&1):3+(i&1);Put(set,pool,op,values[choice]);int mask=0;for(uint j=0;j<3;j++){IntPtr value=Marshal.ReadIntPtr(Cell(pool,j));int id=Array.IndexOf(values,value);Check(id>=0,"Unknown rooted stream");mask|=id<<((int)j*3);}Check(mask==expected[i]&&Marshal.ReadInt64(h,56)==count,"Stream relation differs from JVM: i="+i+", mask="+mask+", expected="+expected[i]+", count="+Marshal.ReadInt64(h,56)+", prior="+count);if((i&63)==63)GC(m,h,values);}
            for(uint op=0;op<3;op++){IntPtr before=Marshal.ReadIntPtr(Cell(pool,op));c=new Context{PC=17,Method=23};IntPtr wrong=values[op==0?3:1];Check(set(ref c,new ulong[]{Bits(wrong)},pool,op)==0&&c.Kind==7&&c.PC==17&&c.Method==23&&Marshal.ReadIntPtr(Cell(pool,op))==before,"Wrong stream type was published");}
            c=new Context{Kind=9,PC=17,Method=23,Depth=3};Check(set(ref c,new ulong[]{0},IntPtr.Zero,0)==0&&c.Kind==9&&c.PC==17&&c.Method==23&&c.Depth==3,"Stream setter changed pending context");
            IntPtr copy=Marshal.AllocHGlobal(64);try{byte[] data=new byte[64];Marshal.Copy(pool,data,0,64);foreach(int off in new[]{0,4,8,16,24,32,40,44,48,56}){Marshal.Copy(data,0,copy,64);if(off==0||off==4||off==40||off==44)Marshal.WriteInt32(copy,off,off==40?2:7);else Marshal.WriteInt64(copy,off,off>=48?1:0);c=new Context();Check(set(ref c,new ulong[]{0},copy,0)==0&&c.Kind==7,"Malformed System stream pool accepted: "+off);}c=new Context();Check(set(ref c,new ulong[]{0},pool,3)==0&&c.Kind==7,"Invalid stream operation accepted");}finally{Marshal.FreeHGlobal(copy);}
            IntPtr foreign=Fn<Create>(m,"boom_heap_create")(65536);Check(foreign!=IntPtr.Zero,"Foreign stream heap failed");try{c=new Context();IntPtr f=obj(foreign,storage(0),ref c);Check(f!=IntPtr.Zero&&c.Kind==0,"Foreign stream storage failed");c=new Context();Check(set(ref c,new ulong[]{Bits(f)},pool,0)==0&&c.Kind==7,"Foreign heap stream accepted");}finally{Check(Fn<Destroy>(m,"boom_heap_destroy")(foreign)!=0,"Foreign stream cleanup failed");}
            GC(m,h,values);Workers(m,r,entryOp==0?new[]{values[1],values[2],IntPtr.Zero}:new[]{values[3],values[4],IntPtr.Zero});GC(m,h,values);
            while(alloc(h,4096,0,267)!=IntPtr.Zero){}while(alloc(h,0,0,267)!=IntPtr.Zero){}long full=Marshal.ReadInt64(h,56);for(int i=0;i<8193;i++){uint op=(uint)(i%3);Put(set,pool,op,values[i%5==0?0:op==0?1+(i&1):3+(i&1)]);Check(Marshal.ReadInt64(h,56)==full,"Full heap stream publication allocated");}
            GC(m,h,values);Put(set,pool,0,values[1]);Put(set,pool,1,values[3]);Put(set,pool,2,values[3]);GC(m,h);Check(Marshal.ReadInt64(h,56)==baseline+3,"Static stream references failed to retain exactly one input, backing and shared print view");Put(set,pool,1,IntPtr.Zero);GC(m,h);Check(Marshal.ReadInt64(h,56)==baseline+3,"Clearing one alias lost a shared stream");Put(set,pool,0,IntPtr.Zero);GC(m,h);Check(Marshal.ReadInt64(h,56)==baseline+1,"Overwritten input graph retained");Put(set,pool,2,IntPtr.Zero);GC(m,h);Check(Marshal.ReadInt64(h,56)==baseline,"Cleared System streams remained roots");
        }finally{if(h!=IntPtr.Zero)Check(Fn<Destroy>(m,"boom_heap_destroy")(h)!=0,"System stream heap cleanup failed");FreeLibrary(m);FreeLibrary(r);}
    }
}
